add('H23-REG-APPLIED-16','ナイロン6と66の原料経路を区別する。',['シクロヘキサン','シクロヘキサノン','アジピン酸','シクロヘキサノンオキシム','εカプロラクタム'],['環状六炭素の出発原料経路に属す。','オキシムの前駆体。','ジアミンとの縮合でナイロン66を作る原料。','Beckmann転位でラクタムへ進む。','環を開いてナイロン6のポリアミド鎖になる。'],3,'ナイロン6はカプロラクタムの開環を利用するポリアミドである。代表経路はシクロヘキサン→シクロヘキサノン→オキシム→カプロラクタム。アジピン酸はヘキサメチレンジアミンとナイロン66を作る原料なので3を選ぶ。ポリアミドという結合種が共通でも原料は共通でない。','organic_polyamide_routes','nylon',['organic_step'])
add('H24-REG-APPLIED-15','主鎖結合と生分解性高分子の代表分類を判定する。',['PGA','ポリL乳酸','PBS','PMMA','ポリR3ヒドロキシブチレート'],['脂肪族ポリエステルとして生分解性分類。','PLAの生分解性で分類される。','PBSは脂肪族ポリエステル。','炭素主鎖の通常PMMAは生分解性高分子に該当しない。','PHBは微生物が作るポリエステル。'],4,'PGA、PLA、PBS、PHBは代表的な生分解性ポリエステルである。PMMAは側鎖にエステルを持つが主鎖はC-Cで、同じ分類に入らないので4。エステルという単語だけで生分解を保証せず、主鎖・分解環境・試験条件を区別する。生分解性は海洋でも直ちに消えるという意味ではない。','organic_biodegradation','biodegradation',['organic_jbpa','organic_jbpa_en'])
add('H24-REG-APPLIED-18','石油留分の分解・改質・選択酸化を製品へ対応させる。',['固体酸の接触分解で高オクタンガソリン','白金/固体酸改質で芳香族','ナフサ熱分解でパラフィンガス','完全酸化を避け選択部分酸化','合成ガスはCO/H2'],['大きな分子の切断でガソリン原料へ。','芳香族化と異性化などによる改質。','主目的のエチレン等は二重結合のあるオレフィンであり語が違う。','目的有機化合物を残すため選択性が必要。','メタノール等の原料となる混合ガス。'],3,'分留は沸点で分け、分解・改質は結合を変える。ナフサの熱分解からエチレン、プロピレン、ブタジエン等を得るので3のパラフィンが不適切。実際の分解生成物は混合物で、飽和ガスが一切ないという意味ではない。接触改質の芳香族と選択酸化・CO/H2合成ガスを別反応として整理する。','organic_petroleum','petroleum',['organic_jpca','organic_gasoline'],ambiguity='原典の750℃を全装置の固定温度としない。水蒸気改質と酸素による部分酸化は別反応で、全工程条件・当時触媒仕様の全文照合は未完了。')
add('H25-REG-APPLIED-14','石油化学原料の留分位置と反応生成物を対応させる。',['ナフサは軽油より高沸点','ナフサ熱分解からエチレン','エチレン酸化からエチレンオキシド','1,3ブタジエンは合成ゴム原料','pキシレン酸化からPET原料酸'],['ナフサは軽質で軽油より低沸点。','二重結合を持つ主要基礎製品。','環状エーテルの酸化生成物。','ジエンの重合をゴムへ利用。','テレフタル酸をエチレングリコールとポリエステルへ。'],1,'ナフサは原油の低沸点側の軽質留分であり、軽油より高沸点とする1が逆である。分留の位置を先に固定し、エチレン→酸化→エチレンオキシド、ブタジエン→ゴム、pキシレン→テレフタル酸→PETという反応・用途の鎖を分けて覚える。','organic_petroleum','petroleum',['organic_jpca_dict','organic_step'])
def directing(q,vals,ans):
 reasons=[]
 for i,v in enumerate(vals,1):
  reasons.append('メチル基はo,p配向、トルエンを先に作りニトロを導入する全対応に合う。' if i==ans else ('ニトロを先に入れる順はm配向・不活性化なので目的の経路に合わない。' if 'ニトロ基/メチル基' in v else 'oニトロトルエンの置換基メチル/ニトロ又は中間トルエン/ニトロベンゼンの対応と異なる。'))
 add(q,'芳香族置換の配向性からoニトロトルエンの導入順を決める。',vals,reasons,ans,'メチル基は環へ電子を供与してo,p位の求電子置換を促し、ニトロ基は電子を吸引してm配向となる。先にメチルを入れてトルエンを作り、その後ニトロを導入する。イだけをベンゼンへ入れたものはニトロベンゼン。この四対応で候補'+str(ans)+'。この経路でもo体だけが100%得られるという意味ではなく、他位置との生成混合を分離する。','organic_aromatic_directing','directing',['organic_directing'])
directing('H25-REG-APPLIED-17',['ニトロ基/メチル基/ニトロベンゼン/トルエン','カルボキシル基/ニトロ基/安息香酸/ニトロベンゼン','ニトロ基/アミノ基/ニトロベンゼン/アニリン','メチル基/ニトロ基/トルエン/ニトロベンゼン','ヒドロキシ基/ニトロ基/フェノール/ニトロベンゼン'],4)
directing('R01-RET-APPLIED-13',['メチル基/ニトロ基/トルエン/ニトロベンゼン','ニトロ基/カルボキシル基/ニトロベンゼン/安息香酸','アミノ基/ニトロ基/アニリン/ニトロベンゼン','ニトロ基/メチル基/ニトロベンゼン/トルエン','ニトロ基/ヒドロキシ基/ニトロベンゼン/フェノール'],1)
add('H26-REG-APPLIED-17','求核性・酸性・配向性と不斉炭素を区別する。',['C4以上アルカンに骨格異性','OH−/Cl−/H2O/H+で求核はH+','電子供与基で芳香族求電子置換促進','カルボン酸/フェノールはアルコールより酸性','2,4ジメチルヘキサンに不斉炭素'],['C4には直鎖と分枝の二骨格。','H+は電子対を受け取る求電子剤であり逆。','中間体安定化で置換を促進する代表傾向。','共役塩基の共鳴安定化等で比較できる。','C4はH・メチル・右エチル・左の分枝鎖の4種を持つ。'],2,'求核剤は電子対を与えて結合を作り、求電子剤はそれを受け取る。H+は求電子側なので2が不適切。OH−とCl−、孤立電子対を持つ水は条件により求核剤となる。2,4ジメチルヘキサンではC2に同じメチルが二つあるが、C4の四置換基は異なり不斉中心となる。名称に分枝があるだけで全炭素を不斉としない。','organic_nucleophile_stereo','structure',['organic_chirality','organic_directing'])
def surf_names(q):
 add(q,'界面活性分子と固体吸着材を区別する。',['けん化','活性炭','臨界ミセル濃度','ソルビタン脂肪酸エステル','ドデシルベンゼンスルホン酸Na'],['脂肪酸塩の石けんを生成。','多孔質の固体吸着材で界面活性分子とは別分類。','界面活性分子の会合が重要になる濃度。','非イオン系の代表。','陰イオン系の代表。'],2,'界面活性剤は親水部と疎水部を同一分子に持つ。けん化は石けん生成、CMCは会合、ソルビタン脂肪酸エステルとアルキルベンゼンスルホン酸塩は代表剤に対応する。活性炭は多孔質固体への吸着に用いられるため、この五候補で最も関係が薄い2。活性炭に界面がないとか吸着しないという説明ではない。','organic_surfactant','surfactant',['organic_cmc'])
surf_names('H27-REG-APPLIED-13');surf_names('H29-REG-APPLIED-17')
def hazards(q,order,ans):
 content={'ether':('ジエチルエーテル揮発・引火','低沸点有機溶媒で蒸気が燃えやすい。'),'peroxide':('過酸化ベンゾイル加熱・摩擦で爆発分解','弱いO-O結合の分解と発熱・感度を持ち、爆発的分解の危険がある。必ず爆発するという無条件則ではない。'),'benzene':('ベンゼン揮発・有毒蒸気','蒸発して有害な暴露を起こし得る。'),'nitro':('ニトロベンゼンは水より軽い','公開ICSCの水=1に対する比重は約1.2で、軽いという記述が逆。'),'acrylic':('アクリル酸は重合しやすい','ビニル結合の重合で発熱し、条件・阻害剤の管理が必要。')}
 add(q,'物質ごとの密度・揮発性・反応性を比較する。',[content[k][0] for k in order],[content[k][1] for k in order],ans,'ニトロベンゼンの相対密度は水=1に対して約1.2である。水より小さいとする候補'+str(ans)+'が不適切。エーテルの揮発・引火、ベンゼン蒸気の有害性、過酸化物の分解、アクリル酸の重合は異なる物性・危険である。爆発や重合は状態・温度・組成に依存し、原典の一般表現を全条件での必然としない。','organic_properties','properties',['organic_nitro','organic_peroxide'],ambiguity='過酸化物の加熱・摩擦を全条件で必ず爆発するとの全称にしない。各候補の出題時SDS・全条件は未照合、公開ICSCの対象性状を参照。')
hazards('H27-REG-APPLIED-14',['ether','peroxide','benzene','nitro','acrylic'],4);hazards('R03-REG-APPLIED-12',['benzene','nitro','peroxide','acrylic','ether'],2)
def combustion(q,m,co,water,vals,ans,formula,ratio,ambiguity=''):
 mc=co*12/44;mh=water*2/18;mo=m-mc-mh
 fs={'トルエン':'C7H8','フェノール':'C6H6O','安息香酸':'C7H6O2','テレフタル酸':'C8H6O4','サリチル酸':'C7H6O3','エタノール':'C2H6O','アセトアルデヒド':'C2H4O','アセトン':'C3H6O','酢酸':'C2H4O2','アクリル酸':'C3H4O2'}
 reasons=[fs[v]+'の原子数比が導出比に'+('一致する。' if i==ans else '一致しない。') for i,v in enumerate(vals,1)]
 sol='完全燃焼で試料CはCO2、試料HはH2Oへ全て移る。炭素質量'+str(co)+'×12/44='+str(round(mc,6))+'mg、水素質量'+str(water)+'×2/18='+str(round(mh,6))+'mg。試料がC,H,Oのみなので酸素質量は差の'+str(round(mo,6))+'mg。各質量を12,1,16で割った原子比は'+ratio+'となる。候補中'+formula+'の'+vals[ans-1]+'だけが合い'+str(ans)+'。組成比だけでは一般の分子式を一意にしないが、提示候補比較で選べる。'
 add(q,'燃焼生成物から元素量を保存して有機化合物を選ぶ。',vals,reasons,ans,sol,'organic_combustion_analysis','combustion',ambiguity=ambiguity,conditions={'試料':str(m)+'mg','CO2':str(co)+'mg','H2O':str(water)+'mg','原子量':'C=12,H=1,O=16'},calc=True)
aro=['トルエン','フェノール','安息香酸','テレフタル酸','サリチル酸']
word='原典は酸素を含むのに芳香族炭化水素と呼ぶ。炭化水素はC,Hのみで名称に疑義がある。数値と候補は保持し、C,H,O有機化合物として条件付きで解く。'
combustion('H28-REG-APPLIED-15',69,154,27,aro,5,'C7H6O3','7:6:3',word)
combustion('R01-REG-APPLIED-13',61,154,27,aro,3,'C7H6O2','7:6:2')
combustion('R07-REG-APPLIED-12',47,132,27,aro,2,'C6H6O','6:6:1',word)
combustion('H29-REG-APPLIED-15',88,176,72,['エタノール','アセトアルデヒド','アセトン','酢酸','アクリル酸'],2,'C2H4O','2:4:1')
combustion('R05-REG-APPLIED-11',92,176,108,['アクリル酸','アセトアルデヒド','アセトン','エタノール','酢酸'],4,'C2H6O','2:6:1')
def polymers(q,vals,ans):
 reasons={'protein':'アミノ酸残基がアミド結合でつながる生体高分子。','nylon':'ナイロン66なら二官能原料の縮合が対応するが、全ナイロンの定義ではなくナイロン6はラクタム開環。','pla':'代表的生分解性ポリエステル。ただし環境条件を伴う。','pvc':'通常PVCは熱可塑性で熱硬化性ではない。','pet':'通常PETは熱可塑性ポリエステル。'}
 names={'protein':'タンパク質はアミノ酸の生体高分子','nylon':'ナイロンはジカルボン酸/ジアミンのポリアミド','pla':'PLAは生分解性','pvc':'PVCは熱硬化性','pet':'PETは熱可塑性'}
 add(q,'高分子の結合・熱応答・生分解性を別軸で比較する。',[names[k] for k in vals],[reasons[k] for k in vals],ans,'PVCは通常の熱可塑性樹脂であり、熱硬化性という候補'+str(ans)+'が公式の不適切肢である。タンパク質・ナイロンはアミド、PET・PLAはエステルを主鎖に持つが、結合種だけで熱応答と生分解性を同一視しない。原典のナイロンの二原料縮合はナイロン66等へ限定すべきで、ナイロン6を含む全称では正確でない。この留保も保持する。','organic_polymer_architecture','polymer',['organic_physical','organic_step','organic_jbpa'],ambiguity='ナイロン全般をジカルボン酸/ジアミン由来へ限定する候補はナイロン6等に当てはまらない。公式PVC肢の説明と別に原典の一般化疑義を残す。')
polymers('H28-REG-APPLIED-17',['protein','nylon','pla','pvc','pet'],4);polymers('R06-REG-APPLIED-17',['nylon','pla','pvc','pet','protein'],3)
def stereos(q,order,ans):
 dd={'methyl':('メチルシクロヘキサンに鏡像異性体','メチル付炭素から環の左右へ進む結合経路が等価で、不斉中心にならない。椅子形の配座異性とは別。'),'benzene':('ベンゼンは共鳴混成体','局在した二つの式は表現で、実分子の環へπ電子が非局在。混合物ではない。'),'cis':('1,2ジメチルシクロプロパンにcis/trans','小環の同じ側と反対側の置換を回転だけでは重ねられず区別できる。'),'acid':('アセチレンはエチレンより酸性','sp炭素のs性50%はsp2の33%より高く、共役塩基を安定化する。'),'radical':('過酸化ベンゾイル加熱でラジカル','O-O結合の均等開裂でラジカルを作る。')}
 add(q,'骨格・立体・共鳴・酸性を分けて有機分子を比較する。',[dd[k][0] for k in order],[dd[k][1] for k in order],ans,'メチルシクロヘキサンでは置換炭素に接する二つの環方向が等価で、四種置換基の不斉中心にならない。鏡像異性体があるという'+str(ans)+'が不適切。環反転でaxial/equatorialが入れ替わる配座と鏡像異性は違う。1,2ジメチルシクロプロパンのcis/trans、ベンゼンの非局在π、アセチレンの酸性、過酸化物のラジカルはそれぞれ別の構造根拠で説明する。','organic_nucleophile_stereo','structure',['organic_chirality','organic_benzene'])
